-- Additive migration; historical workouts remain unassigned because their active plan is unknown.
-- Recovery: do not edit this file after application; inspect SHOW CREATE TABLE and schema_migrations,
-- then use a forward corrective migration if an index, table, column, or FK was only partly created.
-- MySQL DDL is not transactional.
CREATE TABLE vigencias_planes_entrenamiento (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  usuario_id BIGINT UNSIGNED NOT NULL,
  plan_id BIGINT UNSIGNED NOT NULL,
  fecha_inicio DATE NOT NULL,
  fecha_fin DATE DEFAULT NULL,
  usuario_vigente BIGINT UNSIGNED GENERATED ALWAYS AS (IF(fecha_fin IS NULL, usuario_id, NULL)) STORED,
  creado_en DATETIME(3) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_plan_vigencia_usuario_activo (usuario_vigente),
  KEY idx_plan_vigencia_usuario_fechas (usuario_id, fecha_inicio, fecha_fin),
  KEY idx_plan_vigencia_plan (usuario_id, plan_id),
  CONSTRAINT fk_plan_vigencia_plan FOREIGN KEY (plan_id)
    REFERENCES planes_entrenamiento (id) ON DELETE CASCADE,
  CONSTRAINT chk_plan_vigencia_fechas CHECK (fecha_fin IS NULL OR fecha_fin >= fecha_inicio)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE registros_entrenamientos
  ADD COLUMN plan_vigencia_id BIGINT UNSIGNED DEFAULT NULL AFTER usuario_id,
  ADD KEY idx_reg_entrenamientos_plan_vigencia (plan_vigencia_id),
  ADD CONSTRAINT fk_reg_entrenamientos_plan_vigencia FOREIGN KEY (plan_vigencia_id)
    REFERENCES vigencias_planes_entrenamiento (id) ON DELETE SET NULL;
